def main() -> None:
    digests = {}
    for name, rows in FILES.items():
        payload = render(rows)
        (ROOT / name).write_text(payload, encoding="utf-8")
        digests[name] = {"records": len(rows), "sha256": hashlib.sha256(payload.encode()).hexdigest()}
    manifest = {"manifest_id": "measurement_acquisition_calibration_v0_1_0", "as_of": AS_OF, "edition": 1, "status": "specified_unimplemented_open_world", "files": digests, "completion_claim": False, "qualified_implementation_count": 0}
    (ROOT / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(f"BUILD PASS measurement: {len(SOURCES)} sources, {len(CONTEXTS)} contexts, {len(DECISION_ROWS)} decisions, {len(LIBRARIES)} libraries, {sum(len(v) for v in OPS.values())} operations, {len(LENS_ROWS)} lenses")


if __name__ == "__main__":
    main()
